/**
 * Curated fixture city: central Austin, TX. Serves the game with no API key and drives tests.
 *
 * Business names are generic or clearly fictional; ratings, reviews, phones and websites are invented.
 * Public landmarks (parks, the Capitol, the airport, public library, courthouse, police HQ) use real names.
 * `types` use Places API (New) Table A names; a few speculative names (`dmv`, `thrift_store`, `cannabis_store`,
 * `coworking_space`, `homeless_shelter`, `senior_center`, `martial_arts_school`, `music_school`, `dance_studio`,
 * `climbing_gym`, `factory`, `warehouse`, `farmers_market`, `jail`) are included alongside real ones so that
 * `archetypeForTypes` resolves every archetype the game needs.
 */
import type { GooglePlaceData, OpeningPeriod, Weekday } from '../../core/types';

export const AUSTIN_CENTER = { lat: 30.2672, lng: -97.7431 } as const;
export const AUSTIN_BOUNDS = { minLat: 30.22, maxLat: 30.32, minLng: -97.8, maxLng: -97.7 } as const;

const ALL: Weekday[] = [0, 1, 2, 3, 4, 5, 6];
const WK: Weekday[] = [1, 2, 3, 4, 5];
const t = (h: number, m = 0): number => h * 60 + m;
const hrs = (open: number, close: number, days: Weekday[] = ALL): OpeningPeriod[] => days.map((day) => ({ day, open, close }));

export const H24 = hrs(0, 1440);
const GROC = hrs(t(7), t(22));
