const OFFICE = hrs(t(9), t(17), WK);
const GOV = hrs(t(8), t(17), WK);
const RETAIL = [...hrs(t(10), t(21), [1, 2, 3, 4, 5, 6]), ...hrs(t(11), t(18), [0])];
const GYM = [...hrs(t(5), t(23), WK), ...hrs(t(7), t(21), [0, 6])];
const PARK = hrs(t(5), t(22));
const SCHOOL = hrs(t(7, 30), t(16), WK);
const CLINIC = hrs(t(8), t(18), WK);
const URGENT = hrs(t(8), t(20));
const PHARM = [...hrs(t(8), t(21), WK), ...hrs(t(9), t(18), [0, 6])];
const LIB = [...hrs(t(10), t(20), WK), ...hrs(t(10), t(18), [6]), ...hrs(t(12), t(18), [0])];
const CHURCH = [...hrs(t(8), t(13), [0]), ...hrs(t(9), t(16), WK)];
const CINEMA = hrs(t(11), t(25));
const SALON = [...hrs(t(9), t(19), [2, 3, 4, 5, 6]), ...hrs(t(11), t(17), [0])];
const AUTO = [...hrs(t(7, 30), t(18), WK), ...hrs(t(8), t(14), [6])];
const FUN = [...hrs(t(12), t(23), [0, 1, 2, 3, 4]), ...hrs(t(11), t(25), [5, 6])];
const MUSEUM = [...hrs(t(10), t(17), [1, 2, 3, 4, 5, 6]), ...hrs(t(12), t(17), [0])];
const MARKET = hrs(t(9), t(13), [6]);
const DAYCARE = hrs(t(6, 30), t(18), WK);

let seq = 100;
function P(
  slug: string,
  name: string,
  lat: number,
  lng: number,
  primaryType: string,
  extraTypes: string[],
  hours: OpeningPeriod[] | undefined,
  rating: number,
  userRatingCount: number,
  priceLevel: number | undefined,
  address: string,
  summary: string,
  snippets: string[],
  themes: string[],
): GooglePlaceData {
  seq++;
  const types = [...new Set([primaryType, ...extraTypes, 'point_of_interest', 'establishment'])];
  const d: GooglePlaceData = {
    placeId: `mock_${slug}`,
    displayName: name,
    formattedAddress: `${address}, Austin, TX`,
    types,
    primaryType,
    location: { lat, lng },
    rating,
    userRatingCount,
    priceLevel,
    openingPeriods: hours,
    phone: `+1 512-555-0${String(seq).padStart(3, '0')}`,
    website: `https://${slug.replace(/_/g, '')}.example.com`,
    editorialSummary: summary,
    reviewSnippets: snippets,
    reviewThemes: themes,
    businessStatus: 'OPERATIONAL',
  };
  if (priceLevel === undefined) delete d.priceLevel;
  return d;
}

